function workflowStage(n){if(n.kind==='start')return n.acknowledge_prior_quality?'Ready to create a separate visit after the incomplete one':'Ready to start a new monitoring visit';return ({CREATED:'1 of 4 · Checking authorization',AUTHORIZED:'2 of 4 · Reviewing permitted history',VALIDATING:'3 of 4 · Checking safety and eligibility',AWAITING_ACTION:'4 of 4 · Selecting the next eligible action',RECORDING:'Checking and recording saved results',PAUSED:'Session paused'})[n.state]||'Preparing your monitoring session';}
let workflowIntent=null;
async function prepareJourney(){
 const person=S.person.id,mode=S.mode;
 journeyStep=3;
 for(let count=0;count<8;count++){
  if(S.person?.id!==person||S.mode!==mode)throw Error('Participant changed. Reload the selected journey before continuing.');
  const fresh=await api('/neurocontinuum/v1/participants/'+person+'/next-action?mode='+mode);
  journeyData=fresh;journeyError='';render();
  const n=fresh.next_action;
  if(!['start','command'].includes(n.kind)){workflowIntent=null;if(n.kind==='summary')journeyStep=4;return;}
  const path=n.kind==='start'?'/neurocontinuum/v1/participants/'+person+'/sessions?mode='+mode:'/neurocontinuum/v1/sessions/'+n.session_id+'/commands?mode='+mode;
  const key=JSON.stringify([person,mode,n.kind,n.session_id,n.expected_version,n.command,n.checkin_id,n.acknowledge_prior_quality===true]);
  // A distinct, fresh visit after an incomplete visit is not an equivalent retest.
  // Never omit acknowledgement: the authoritative backend requires this field.
  if(n.kind==='start'&&!n.checkin_id)throw Error('No eligible check-in was selected. Review your current accessibility check-in.');
  if(n.kind==='start'&&n.acknowledge_prior_quality===true&&workflowIntent?.key!==key){
   if(!confirm('The earlier visit was incomplete and its measurements may be unreliable. Start a SEPARATE research visit with your new check-in? Earlier records will remain unchanged, and results will not be assumed comparable.')){
    S.notice='You can review the earlier visit instead. Nothing was started.';
    return;
   }
  }
  if(workflowIntent?.key!==key)workflowIntent={key,path,body:n.kind==='start'?{
   operation_id:crypto.randomUUID(),session_id:crypto.randomUUID(),checkin_id:n.checkin_id,
   acknowledge_prior_quality:n.acknowledge_prior_quality===true
  }:{operation_id:crypto.randomUUID(),expected_version:n.expected_version,action:n.command,signs:[]}};
  try{await api(path,'POST',workflowIntent.body);}catch(e){
   const reason=String(e.message||e);
   if(reason.includes('confirm_prior_incomplete_quality_before_new_visit'))throw Error('Please confirm the earlier visit was incomplete before starting a separate visit. Refresh the page and retry.');
   if(reason.includes('checkin_already_linked_create_fresh_preparation')||reason.includes('new_preparation_after_prior_incomplete_visit_required'))throw Error('This check-in belongs to an earlier visit. Complete a NEW accessibility check-in, then return here.');
   throw Error('Workflow preparation stopped: '+reason+' Your saved progress is retained. Try again after reviewing the current step.');
  }
  workflowIntent=null;
  const updated=await api('/neurocontinuum/v1/participants/'+person+'/next-action?mode='+mode);
  journeyData=updated;render();
  const next=updated.next_action;
  if(next.kind===n.kind&&next.session_id===n.session_id&&next.expected_version===n.expected_version&&next.command===n.command)throw Error('The server did not advance the workflow. Review restrictions and recovery in NeuroContinuum.');
  if(!['start','command'].includes(next.kind)){if(next.kind==='summary')journeyStep=4;return;}
 }
 throw Error('Preparation reached its transition limit. Saved progress is retained; review the current session before continuing.');
}
