let setupStep=0;
function profileForm(){
 const panel=fullProfileForm();
 if(S.person)return panel;
 const form=panel.querySelector('form'),sets=[...form.querySelectorAll('fieldset')];
 const labels=['Personal details','Accessibility','Display','Assistance & consent'];
 setupStep=Math.min(setupStep,sets.length-1);
 const progress=h('p',{class:'setup-progress',role:'status'},'Step '+(setupStep+1)+' of 5 · '+labels[setupStep]);
 form.prepend(progress);
 sets.forEach((el,i)=>{el.hidden=i!==setupStep;el.disabled=i!==setupStep||S.busy||!!S.pendingProfile;});
 const consent=form.querySelector('label.check');if(consent){consent.hidden=setupStep!==3;consent.querySelector('input').disabled=setupStep!==3;}
 const submit=form.querySelector('button[type=submit]');submit.textContent=setupStep<3?'Continue':'Save profile & continue to health';
 form.addEventListener('submit',e=>{if(setupStep<3){e.preventDefault();e.stopImmediatePropagation();setupStep++;render();}},true);
 if(setupStep>0)form.querySelector('.actions').prepend(button('Back',()=>{setupStep--;render();},'secondary'));
 return panel;
}

