/* BAINP_PROFILE_PHOTO_V1: participant-scoped, browser-only avatar. No medical API calls. */
function profilePhotoWidget(participantId, displayName){
 const root=document.createElement('section');root.className='bainp-avatar-card';
 const head=document.createElement('div');head.className='bainp-avatar-head';
 const avatar=document.createElement('div');avatar.className='bainp-avatar-preview';
 const initials=document.createElement('span');initials.textContent=(displayName||'P').trim().split(/\s+/).slice(0,2).map(x=>x.charAt(0)).join('').toUpperCase()||'P';avatar.append(initials);
 const copy=document.createElement('div');const title=document.createElement('h2');title.textContent='Profile photo';const subtitle=document.createElement('p');subtitle.textContent='Optional · stored on this browser only';copy.append(title,subtitle);head.append(avatar,copy);
 const actions=document.createElement('div');actions.className='bainp-avatar-actions';
 const input=document.createElement('input');input.type='file';input.accept='image/jpeg,image/png,image/webp';input.className='bainp-avatar-file';input.setAttribute('aria-label','Choose profile photo');
 const choose=document.createElement('button');choose.type='button';choose.className='bainp-avatar-action';choose.textContent='Upload photo';
 const remove=document.createElement('button');remove.type='button';remove.className='bainp-avatar-action secondary';remove.textContent='Remove photo';remove.disabled=true;
 const status=document.createElement('p');status.className='bainp-avatar-status';status.setAttribute('role','status');status.textContent='JPEG, PNG or WebP · up to 8 MB';
 const note=document.createElement('p');note.className='bainp-avatar-privacy';note.textContent='Private to this browser profile. Not uploaded, synced, or included in medical records. On a shared computer, remove the photo before leaving.';
 actions.append(choose,remove,input);root.append(head,actions,status,note);
 const key='active:'+String(participantId);let objectUrl=null;
 const setPreview=blob=>{
   if(objectUrl){URL.revokeObjectURL(objectUrl);objectUrl=null;}
   avatar.replaceChildren();
   if(!blob){avatar.append(initials);remove.disabled=true;choose.textContent='Upload photo';return;}
   objectUrl=URL.createObjectURL(blob);
   const img=document.createElement('img');img.alt='Your chosen profile photo';img.src=objectUrl;img.onload=()=>{if(objectUrl){URL.revokeObjectURL(objectUrl);objectUrl=null;}};
   img.onerror=()=>{avatar.replaceChildren(initials);status.textContent='Saved photo cannot be displayed.';};
   avatar.append(img);remove.disabled=false;choose.textContent='Replace photo';
 };
 const db=()=>new Promise((resolve,reject)=>{
   if(!('indexedDB' in window)){reject(new Error('Browser storage is unavailable'));return;}
   const req=indexedDB.open('bainp-private-profile-photos-v1',1);
   req.onupgradeneeded=()=>{if(!req.result.objectStoreNames.contains('photos'))req.result.createObjectStore('photos');};
   req.onsuccess=()=>resolve(req.result);req.onerror=()=>reject(req.error||new Error('Photo store unavailable'));
 });
 const operate=async(mode,blob)=>{
   const database=await db();
   try{return await new Promise((resolve,reject)=>{
     const transaction=database.transaction('photos',mode==='read'?'readonly':'readwrite');
     const store=transaction.objectStore('photos');
     const request=mode==='read'?store.get(key):mode==='delete'?store.delete(key):store.put(blob,key);
     let result=null;request.onsuccess=()=>{result=request.result;};request.onerror=()=>reject(request.error||new Error('Photo operation failed'));
     transaction.oncomplete=()=>resolve(result);transaction.onerror=()=>reject(transaction.error||new Error('Photo storage failed'));
     transaction.onabort=()=>reject(transaction.error||new Error('Photo operation cancelled'));
   });}finally{database.close();}
 };
 const compress=async(file)=>{
   const accepted=['image/jpeg','image/png','image/webp'];
   if(!accepted.includes(file.type))throw new Error('Choose a JPEG, PNG or WebP image.');
   if(file.size===0||file.size>8*1024*1024)throw new Error('Choose an image smaller than 8 MB.');
   let bitmap;
   try{bitmap=await createImageBitmap(file);}catch(_){throw new Error('The selected image cannot be decoded.');}
   try{
     if(bitmap.width<16||bitmap.height<16||bitmap.width>10000||bitmap.height>10000)throw new Error('Image dimensions are unsupported.');
     const canvas=document.createElement('canvas');canvas.width=320;canvas.height=320;
     const ctx=canvas.getContext('2d');if(!ctx)throw new Error('Image processing is unavailable.');
     const side=Math.min(bitmap.width,bitmap.height);const x=(bitmap.width-side)/2;const y=(bitmap.height-side)/2;
     ctx.fillStyle='#f8f5ec';ctx.fillRect(0,0,320,320);ctx.drawImage(bitmap,x,y,side,side,0,0,320,320);
     const output=await new Promise(resolve=>canvas.toBlob(resolve,'image/jpeg',0.86));
     if(!output)throw new Error('Could not prepare the profile photo.');
     return output;
   }finally{bitmap.close();}
 };
 choose.addEventListener('click',()=>input.click());
 input.addEventListener('change',async()=>{
   const file=input.files&&input.files[0];if(!file)return;
   choose.disabled=true;status.textContent='Preparing photo…';
   try{const blob=await compress(file);await operate('write',blob);if(!root.isConnected)return;setPreview(blob);status.textContent='Saved on this browser. Photo is not sent to BAINP servers.';}
   catch(e){status.textContent=e.message||'Photo could not be saved.';}
   finally{choose.disabled=false;input.value='';}
 });
 remove.addEventListener('click',async()=>{
   remove.disabled=true;status.textContent='Removing photo…';
   try{await operate('delete');if(!root.isConnected)return;setPreview(null);status.textContent='Photo removed from this browser.';}
   catch(e){status.textContent=e.message||'Could not remove photo.';remove.disabled=false;}
 });
 void operate('read').then(blob=>{if(root.isConnected&&blob)setPreview(blob);}).catch(()=>{if(root.isConnected)status.textContent='Local photo storage unavailable. Browser storage may be disabled.';});
 return root;
}

