async function profilePermissions(root,pid,mode){
 const feedback=h('p',{role:'status','aria-live':'polite'},'Loading…');root.append(feedback);
 try{
  const path='/neurocontinuum/v1/participants/'+encodeURIComponent(pid);
  const data=await api(path+'/workspace?mode='+mode);if(!root.isConnected)return;
  let current=data.consent,intent=null;const fields={};
  const labels={enabled:'Coordinate my monitoring workflow and preserve its decisions.',assessment_allowed:'Allow the existing cognitive assessment pathway. Digital results alone are not a diagnosis.',history_allowed:'Use my permitted historical observations to inform monitoring.',case_tracking:'Allow local review-case tracking. Saving a case does not contact a clinician.'};
  const form=h('form',{},h('p',{},'Choose each scope separately. Leave optional scopes unchecked. Existing settings are shown below.'));
  for(const [key,label]of Object.entries(labels)){fields[key]=h('input',{type:'checkbox',checked:!!current[key]});form.append(h('label',{class:'check'},fields[key],label));}
  form.addEventListener('change',()=>{S.dirty=true;intent=null;});
  const save=h('button',{type:'submit'},'Save my permissions');form.append(save);
  form.addEventListener('submit',async event=>{event.preventDefault();save.disabled=true;try{
   intent??={operation_id:crypto.randomUUID(),expected_revision:current.revision,...Object.fromEntries(Object.entries(fields).map(([key,input])=>[key,input.checked]))};
   await api(path+'/consent?mode='+mode,'PUT',intent);
   const updated=await api(path+'/workspace?mode='+mode);current=updated.consent;intent=null;S.dirty=false;journeyData=null;
   feedback.textContent=uiText('Permissions saved.',S.lang);
  }catch(error){feedback.textContent=error.message;}finally{save.disabled=false;}});
  root.append(form,h('p',{},'Optional health storage consent is requested separately when you save health details. Clear those details to remove that optional record. Backups may retain earlier data.'),h('p',{},'Camera, microphone, wearable, EEG, passive research and external sharing are not authorized by these controls. No new sensor collection is activated by this update.'));
  feedback.textContent='';
 }catch(error){feedback.textContent=error.message;root.append(button('Retry',()=>{root.replaceChildren();void profilePermissions(root,pid,mode);},'secondary'));}
}

function calendarAge(value,today=new Date()){
 if(!/^\d{4}-\d{2}-\d{2}$/.test(value||''))return null;
 const [y,m,d]=value.split('-').map(Number),date=new Date(y,m-1,d);
 if(date.getFullYear()!==y||date.getMonth()!==m-1||date.getDate()!==d||date>today)return null;
 return today.getFullYear()-y-((today.getMonth()+1<m||(today.getMonth()+1===m&&today.getDate()<d))?1:0);
}
function birthDateField(){
 const box=h('div',{class:'field'}),out=h('p',{role:'status'});
 const input=h('input',{id:'field-birth-date',type:'date',value:S.form.birth_date||'',required:!S.person});
 const show=()=>{const age=calendarAge(input.value);out.textContent=uiText('Calculated age',S.lang)+': '+(age===null?'—':age);input.setCustomValidity(input.value&&(age===null||age<18||age>110)?uiText('This adult prototype supports ages 18–110.',S.lang):'');if(age!==null&&age>=18&&age<=110)S.form.age=age;};
 input.addEventListener('input',()=>{S.form.birth_date=input.value||null;S.dirty=true;show();});show();
 box.append(h('label',{for:'field-birth-date'},'Date of birth'),input,out,h('p',{class:'muted'},'Age is calculated from date of birth. Existing assessment snapshots are not rewritten.'));
 if(S.person&&!S.form.birth_date)box.append(h('p',{},'Previously recorded age: '+S.form.age));
 return box;
}

