    const expected=shape.reduce((a,b)=>a*b,1);if(expected>14000000)throw Error('MRI display volume exceeds dashboard memory limit; open NeuroTwin');
    const binary=atob(encoded),v=Uint8Array.from(binary,c=>c.charCodeAt(0));if(v.length!==expected)throw Error('MRI package volume dimensions mismatch');
    const real={pack,shape,v};state.real=real;state.loadedHash=hash;range.max=String(shape[2]-1);range.value=String(Math.floor(shape[2]/2));drawSlice();
    await threeDimensional(real);status(mstate,'Verified linked MRI · '+(pack.metadata?.cohort||'research')+' · '+(pack.metadata?.visit||id)+' · source checked '+new Date().toLocaleTimeString());
