   for(let x=0;x<nx;x++)for(let y=0;y<ny;y++){const a=v[x*ny*nz+y*nz+k],j=((ny-y-1)*nx+x)*4;img.data[j]=img.data[j+1]=img.data[j+2]=a;img.data[j+3]=255}
