   try{status(estate,'Retrieving recorded waveform…');const d=await np('/subjects/'+sub+'/waveform?'+new URLSearchParams({start_s:String(state.position),duration_s:'5',channels:'4',max_points:'900'}));if(state.stopped)return;drawEEG(d);status(estate,'Source recording '+sub+' · replay at '+state.position+' s · research only');}
