     if(!Array.isArray(d.subject_records))throw Error('Research subject index missing');subject.replaceChildren();for(const r of d.subject_records){const opt=document.createElement('option');opt.value=r.subject;opt.textContent=r.subject+' · '+r.status;subject.append(opt)}
