/* BAINP_WORKSPACE_DIRECTORY_V1_BEGIN - progressive UI enhancement only */
(()=>{
'use strict';
const areas={
 monitoring:{title:'Keep your brain-health picture connected',desc:'Explore available longitudinal, wearable, digital-twin, and brain–body context workspaces. Measurements and status come from the original BAINP engines.'},
 care:{title:'Turn observations into clearer next steps',desc:'Review reported contributors, follow-up workflows, and preventive education. These tools support understanding and coordination; they do not replace clinical care.'},
 evidence:{title:'Understand the evidence behind each decision',desc:'Trace source records, review data-quality limitations, and inspect the evidence supporting research and monitoring conclusions.'},
 research:{title:'Explore research data and analysis',desc:'Access MRI, EEG, and validation workspaces where authorized. Research datasets and participant records remain separate unless verified linkage exists.'},
 all:{title:'Explore the connected BAINP ecosystem',desc:'Find every workspace available to your account, organized across assessment, monitoring, care, evidence, and research.'}
};
const explain={
 'NeuroContinuum':'A guided journey connecting intake, assessments, monitoring, and the next appropriate step.',
 'NeuroQuest':'Uses available history and concerns to explain which assessment or review may be appropriate next.',
 'NeuroCognition X':'Runs cognitive research tasks and keeps session results and quality limitations available for review.',
 'NeuroSense':'Tracks authorized wearable and movement observations, data completeness, and signal quality.',
 'NeuroTwin X':'Brings verified MRI, cognition, EEG, and other observations into a longitudinal workspace without assuming unverified links.',
 'NeuroShadow':'Explores optional interaction-based research signals, with availability subject to consent and data quality.',
 'Brain–Body Context':'Combines authorized brain, body, behavior, and clinical context while preserving source provenance.',
 'NeuroMimic':'Organizes reported factors and potential contributors for research exploration, not causal diagnosis.',
 'CareLoop':'Supports follow-up plans, review statuses, and care coordination where access permits.',
 'NeuroSim':'Explains prevention and lifestyle scenarios for education without presenting them as validated clinical forecasts.',
 'NeuroProof':'Documents the evidence, provenance, and review status behind decisions and derived outputs.',
 'NeuroGraph':'Shows relationships between evidence items and sources without treating associations as proof of causality.',
 'NeuroGuard':'Reviews data quality, reliability, safety constraints, and restrictions before presenting conclusions.',
 'NeuroVision':'Examines available MRI scans, structural views, source information, and quality-reviewed imaging measurements.',
 'NeuroPulse':'Explores authorized EEG recordings and signal characteristics, with research data separated from patient-linked data.',
 'NeuroSignal ARENA':'Provides validation, comparison, and benchmarking reports for research methods and models.'
};
const route=()=>{const match=location.hash.match(/^#\/workspace\/(monitoring|care|evidence|research|all)(?:[/?]|$)/);return match?match[1]:null;};
let busy=false;
function update(){if(busy)return;busy=true;try{
 const area=route();document.body.classList.toggle('bainp-directory-upgraded',!!area);
 if(!area)return;
 const app=document.querySelector('#app');if(!app)return;
 const grid=app.querySelector('.module-grid');const input=app.querySelector('input[type="search"]');
 const main=grid?.closest('main')||grid?.parentElement;if(!grid||!input||!main)return;
 grid.classList.add('directory-grid-enhanced');
 const old=main.querySelector('.directory-intro');if(old && old.dataset.area!==area)old.remove();
 if(!main.querySelector('.directory-intro')){
  const hero=document.createElement('section');hero.className='directory-intro';hero.dataset.area=area;hero.setAttribute('aria-label',area+' workspaces introduction');
  const copy=document.createElement('div');
  const kicker=document.createElement('p');kicker.className='directory-kicker';kicker.textContent='BAINP · CONNECTED WORKSPACES';
  const heading=document.createElement('h2');heading.textContent=areas[area].title;
  const description=document.createElement('p');description.textContent=areas[area].desc;
  copy.append(kicker,heading,description);
  const counter=document.createElement('div');counter.className='directory-count';counter.setAttribute('aria-label','Available workspaces');
  const n=document.createElement('strong');n.textContent=String(grid.querySelectorAll('.module-tile').length);
  const caption=document.createElement('span');caption.textContent='available workspaces';counter.append(n,caption);
  hero.append(copy,counter);main.insertBefore(hero,input.closest('.directory-search-bar')||input);
 }
 if(!input.closest('.directory-search-bar')){
  const wrap=document.createElement('div');wrap.className='directory-search-bar';
  const label=document.createElement('label');label.textContent='FIND A WORKSPACE';if(!input.id)input.id='bainp-directory-search';label.htmlFor=input.id;
  input.parentNode.insertBefore(wrap,input);wrap.append(label,input);
  const note=document.createElement('p');note.className='directory-search-note';note.textContent='Search only workspaces available to your signed-in account. Existing access controls remain in effect.';wrap.append(note);
 }
 for(const tile of grid.querySelectorAll('.module-tile')){
  const heading=tile.querySelector('h2');const label=heading?.textContent.trim();const description=explain[label];
  if(!description)continue;
  if(!tile.querySelector('.directory-engine-detail')){
   const p=document.createElement('p');p.className='directory-engine-detail';p.textContent=description;
   const open=tile.querySelector('.open-label');if(open)tile.insertBefore(p,open);else tile.append(p);
  }
 }
}finally{busy=false;}}
let scheduled=false;function queue(){if(scheduled)return;scheduled=true;queueMicrotask(()=>{scheduled=false;update();});}
let observer;function start(){observer=new MutationObserver(mutations=>{
 if(mutations.every(m=>m.target?.closest?.('.directory-intro,.directory-search-bar,.directory-engine-detail')))return;
 queue();});observer.observe(document.querySelector('#app')||document.body,{subtree:true,childList:true});queue();}
window.addEventListener('hashchange',queue);
if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',start,{once:true});else start();
})();
/* BAINP_WORKSPACE_DIRECTORY_V1_END */

/* BAINP_SESSIONS_DESCRIPTIONS_V1_BEGIN */
(() => {
  'use strict';
  const descriptions = Object.freeze({
    'NeuroContinuum': 'Guides you through your brain-health journey, connecting your profile, completed assessments, monitoring history, and appropriate next actions.',
    'NeuroQuest': 'Uses available profile information, concerns, and prior assessments to explain which assessment or review may be most appropriate next.',
    'NeuroCognition X': 'Provides interactive cognitive research tasks for memory, attention, and other domains, with recorded results and quality information for later review.'
  });
  const active = () => /^#\/workspace\/sessions(?:[/?]|$)/.test(window.location.hash);
  let running = false;
  function enhance() {
    if (running) return;
    running = true;
    try {
      const enabled = active();
      document.body.classList.toggle('bainp-sessions-descriptions-v1', enabled);
      if (!enabled) return;
      const grid = document.querySelector('#app .module-grid');
      if (!grid) return;
      grid.querySelectorAll('.module-tile').forEach(tile => {
        const name = tile.querySelector('h2')?.textContent?.trim();
        const description = descriptions[name];
        if (!description) return;
        if (tile.querySelector('.bainp-session-description')) return;
        const paragraph = document.createElement('p');
        paragraph.className = 'bainp-session-description';
        paragraph.textContent = description;
        const action = tile.querySelector('.open-label');
        if (action) tile.insertBefore(paragraph, action);
        else tile.appendChild(paragraph);
      });
    } finally { running = false; }
  }
  let queued = false;
  const schedule = () => {
    if (queued) return;
    queued = true;
    queueMicrotask(() => { queued = false; enhance(); });
  };
  function init() {
    const root = document.querySelector('#app') || document.body;
    const observer = new MutationObserver(records => {
      if (records.every(record => [...record.addedNodes].every(node => node.nodeType === 1 && node.classList?.contains('bainp-session-description')))) return;
      schedule();
    });
    observer.observe(root, { childList:true, subtree:true });
    schedule();
  }
  window.addEventListener('hashchange', schedule);
  if (document.readyState === 'loading') document.addEventListener('DOMContentLoaded', init, {once:true});
  else init();
})();
/* BAINP_SESSIONS_DESCRIPTIONS_V1_END */
